with dates(as_of) as (values ('2025-12-31'::date), ('2026-08-31'::date)), balances as (select d.as_of,a.id,a.account_code,a.account_name,a.account_name_ar,a.account_type,a.account_subtype,a.account_level,a.is_header,a.is_active,a.balance_type,count(*) as line_count, sum(coalesce(l.debit_amount,0)) as debits, sum(coalesce(l.credit_amount,0)) as credits from dates d join public.journal_entries e on e.entry_date<=d.as_of and e.company_id='24bc0b21-4e2d-4413-9842-31719a3669f4' and e.status='posted' join public.journal_entry_lines l on l.journal_entry_id=e.id join public.chart_of_accounts a on a.id=l.account_id and a.company_id=e.company_id group by d.as_of,a.id,a.account_code,a.account_name,a.account_name_ar,a.account_type,a.account_subtype,a.account_level,a.is_header,a.is_active,a.balance_type) select jsonb_build_object('extracted_at',current_timestamp,'company',(select jsonb_build_object('name',name,'name_ar',name_ar,'commercial_register',commercial_register,'currency',currency) from public.companies where id='24bc0b21-4e2d-4413-9842-31719a3669f4'),'balances',(select jsonb_agg(to_jsonb(b) order by as_of,account_code) from balances b)) as evidence;
